+#ifndef ARM_ACLE_INTRINS_H
+#define ARM_ACLE_INTRINS_H
+
+#include <stdint.h>
+#if defined(_MSC_VER) && !defined(__clang__)
+#  include <intrin.h>
+#elif defined(HAVE_ARM_ACLE_H)
