+        len -= k;
+
+        vs1 = __lsx_vinsgr2vr_w(zero, adler0, 0);
+        vs2 = __lsx_vinsgr2vr_w(zero, adler1, 0);
+
+        vs3 = __lsx_vldi(0);
+        vs2_0 = __lsx_vldi(0);
+        vs1_0 = vs1;
+
+        while (k >= 32) {
